import com.bridger.momentum.*;import java.util.*;
public class TechniqueColorsRegression {
 public static void main(String[] args){BridgeConfig.displayMode="ALL";String[] labels={"1.0 Flat","1.05 Flat","1.1 Flat","1.15 Flat","1.2 Flat","4b Flat","Other Flat","Tap Speed #1","4b Tap Speed #1","Hold Speed #1","4b Hold Speed #1","5b Late","6b Late","Turn","Fail Tap/4b","Head hitter","Plates","Jump #1"};Set<Integer> unique=new HashSet<>();for(int i=0;i<labels.length;i++){JumpEntry.EntryType type=i<=6?JumpEntry.EntryType.FLAT:i==13?JumpEntry.EntryType.TURN:i==14?JumpEntry.EntryType.FAIL_TAP:i==15?JumpEntry.EntryType.HEAD_HITTER:i==16?JumpEntry.EntryType.PLATES:JumpEntry.EntryType.TAP;JumpEntry e=new JumpEntry(labels[i],.5,.5,0,9,type);int part=EntryFormatter.labelPart(e);if(part!=i+15||!unique.add(part))throw new AssertionError("Technique color collision: "+labels[i]);BridgeConfig.colors[part]="d";if(!EntryFormatter.format(e).contains("\u00a7d"+labels[i]))throw new AssertionError("Label color not applied");OverlayStyle.part(part,0xFF123456);if(!EntryFormatter.hudLines(Arrays.asList(e)).get(0).contains(OverlayStyle.color(part)+labels[i]))throw new AssertionError("RGB label color missing");}BridgeConfig.save();BridgeConfig.colors[17]="f";BridgeConfig.load();if(!BridgeConfig.colors[17].equals("d"))throw new AssertionError("Technique color not saved");System.out.println("PASS independent 18 technique label colors, HUD RGB and persistence");}
}
